pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(address caller, uint256 newAmount) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        uint256 oldLimit = c.currentBetLimit();
        bool reverted;
        vm.prank(caller);
        try c.AdjustBetAmounts(newAmount) { reverted = false; } catch { reverted = true; }
        uint256 newLimit = c.currentBetLimit();
        assertTrue((caller == c.owner() && !reverted && newLimit == newAmount) || (caller != c.owner() && (reverted ? newLimit == oldLimit : false)));
    }
}

