contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(true);
        bool reverted;
        // We need to ensure the caller is not the owner, and we simulate this by using `this` which is not the owner.
        // But OpenToThePublic has onlyOwner modifier in original, so any call from non-owner should revert.
        // We can call it from this contract, which is not the owner.
        try c.OpenToThePublic() { reverted = false; } catch { reverted = true; }
        bool isOwner = (address(this) == c.owner());
        assert(!isOwner ? reverted : true);
    }
}

