pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount, address caller, bool toggleOpen) public {
        vm.assume(caller != address(this));
        bool openBefore = c.openToPublic();
        if (toggleOpen) {
            vm.prank(caller);
            try c.OpenToThePublic() {} catch {}
        }
        vm.prank(caller);
        try c.AdjustBetAmounts(amount) {} catch {}
        bool openAfter = c.openToPublic();
        assertTrue(openBefore == openAfter);
    }
}
